"""Native Vulkan Hulk: select a synthetic draw's own RT/depth binding.

Reject a packet when its writable surfaces cannot be unambiguously recovered.
No game assets/shader bytes, no Xenos host draw or DX12 fallback.
"""
import json, subprocess, sys
from pathlib import Path
