EDITS=json.loads("[{\"path\":\"src/state.h\",\"old\":\"  bool LastWrite(uint32_t reg, uint32_t& value) const;\",\"new\":\"  uint32_t HulkRegisterAtDraw(uint32_t reg) const;\\n  bool LastWrite(uint32_t reg, uint32_t& value) const;\"},{\"path\":\"src/state.cpp\",\"old\":\"bool StateTracker::LastWrite(uint32_t reg, uint32_t& value) const {\",\"new\":\"uint32_t StateTracker::HulkRegisterAtDraw(uint32_t reg) const {\\n  return initialized_ && reg < rex::graphics::RegisterFile::kRegisterCount\\n             ? std::byteswap(image_[reg]) : 0u;\\n}\\n\\nbool StateTracker::LastWrite(uint32_t reg, uint32_t& value) const {\"},{\"path\":\"src/renderer.cpp\",\"old\":\"#include <rex/graphics/register_file.h>\",\"new\":\"#include <rex/graphics/register_file.h>\\n#include <rex/graphics/registers.h>\"},{\"path\":\"src/renderer.cpp\",\"old\":\"#include <memory>\\n#include <mutex>\",\"new\":\"#include <memory>\\n#include <mutex>\\n#include <map>\\n#include <utility>\"},{\"path\":\"src/renderer.cpp\",\"old\":\"void CaptureDraw(const TrackedCall& tracked, StateTracker& tracker, const uint8_t* base) {\",\"new\":\"// Resolve synthetic PM4 draws using the GPU register image at each packet,\\n// not the XDK device-shadow pointers after the entire unhooked gap.\\nusing HulkSurfaceIdentity = std::pair<uint32_t, uint32_t>;\\nstd::mutex g_hulk_surface_history_mutex;\\nstd::array<std::map<HulkSurfaceIdentity, GuestSurface>, 5> g_hulk_surface_history;\\nHulkSurfaceIdentity HulkSurfaceKey(uint32_t surface_info, uint32_t info) {\\n  return {surface_info & 0x0003FFFFu, info & 0x000F0FFFu};\\n}\\nvoid HulkRememberSurface(const GuestSurface& surface, uint32_t slot) {\\n  if (!surface || slot >= 5 || !surface.width || !surface.height) return;\\n  std::lock_guard<std::mutex> guard(g_hulk_surface_history_mutex);\\n  auto& remembered = g_hulk_surface_history[slot];\\n  remembered[HulkSurfaceKey(surface.surface_info, surface.info)] = surface;\\n  if (remembered.size() > 256) remembered.erase(remembered.begin());\\n}\\nbool HulkPacketSurfaces(StateTracker& tracker, const uint8_t* base, uint32_t device,\\n                        std::array<GuestSurface, 5>& out) {\\n  namespace rg = rex::graphics;\\n  const uint32_t gpu_surface = tracker.HulkRegisterAtDraw(rg::XE_GPU_REG_RB_SURFACE_INFO);\\n  if (!(gpu_surface & 0x3FFFu)) return false;\\n  const uint32_t gpu_color_mask = tracker.HulkRegisterAtDraw(\\n      rg::reg::RB_COLOR_MASK::register_index);\\n  const uint32_t gpu_depth_control = tracker.HulkRegisterAtDraw(\\n      rg::reg::RB_DEPTHCONTROL::register_index);\\n  bool has_target = false, unresolved = false;\\n  for (uint32_t slot = 0; slot < 5; ++slot) {\\n    if (slot < 4 && !((gpu_color_mask >> (4 * slot)) & 0xFu)) continue;\\n    if (slot == 4 && !(gpu_depth_control & 0x3u)) continue;\\n    const uint32_t gpu_info = tracker.HulkRegisterAtDraw(\\n        slot < 4 ? rg::reg::RB_COLOR_INFO::rt_register_indices[slot]\\n                 : rg::reg::RB_DEPTH_INFO::register_index);\\n    const HulkSurfaceIdentity gpu_key = HulkSurfaceKey(gpu_surface, gpu_info);\\n    const GuestSurface bound = ReadBoundSurface(base, device, slot);\\n    if (bound && HulkSurfaceKey(bound.surface_info, bound.info) == gpu_key) {\\n      out[slot] = bound;\\n      HulkRememberSurface(bound, slot);\\n      has_target = true;\\n      continue;\\n    }\\n    {\\n      std::lock_guard<std::mutex> guard(g_hulk_surface_history_mutex);\\n      const auto it = g_hulk_surface_history[slot].find(gpu_key);\\n      if (it != g_hulk_surface_history[slot].end()) {\\n        out[slot] = it->second;\\n        has_target = true;\\n        continue;\\n      }\\n    }\\n    unresolved = true;\\n  }\\n  if (!has_target || unresolved) {\\n    static std::atomic<uint64_t> rejected{0};\\n    const uint64_t n = ++rejected;\\n    if (n <= 12 || n % 10000 == 0)\\n      REXLOG_WARN(\\\"[HULK/PM4-SURFACE] skipped ambiguous synthetic RT/depth binding; total={}\\\", n);\\n    return false;\\n  }\\n  return true;\\n}\\n\\nvoid CaptureDraw(const TrackedCall& tracked, StateTracker& tracker, const uint8_t* base,\\n                 const std::array<GuestSurface, 5>* packet_surfaces = nullptr) {\"},{\"path\":\"src/renderer.cpp\",\"old\":\"  for (uint32_t i = 0; i < 5; ++i) c.surfaces[i] = ReadBoundSurface(base, tracked.device, i);\\n  c.programs[0] = tracker.vertex_program_ptr();\",\"new\":\"  for (uint32_t i = 0; i < 5; ++i) {\\n    c.surfaces[i] = packet_surfaces ? (*packet_surfaces)[i] : ReadBoundSurface(base, tracked.device, i);\\n    if (!packet_surfaces) HulkRememberSurface(c.surfaces[i], i);\\n  }\\n  c.programs[0] = tracker.vertex_program_ptr();\"},{\"path\":\"src/renderer.cpp\",\"old\":\"  c.surfaces[0] = ReadBoundSurface(base, device, std::min(flags & 7u, 4u));\",\"new\":\"  c.surfaces[0] = ReadBoundSurface(base, device, std::min(flags & 7u, 4u));\\n  HulkRememberSurface(c.surfaces[0], std::min(flags & 7u, 4u));\"},{\"path\":\"src/renderer.cpp\",\"old\":\"void OnLeave(const TrackedCall& tracked, StateTracker& tracker, PPCContext& ctx, uint8_t* base) {\\n  (void)ctx;\\n  if (tracked.call != g_call.call) return;\",\"new\":\"void OnLeave(const TrackedCall& tracked, StateTracker& tracker, PPCContext& ctx, uint8_t* base) {\\n  (void)ctx;\\n  if (tracked.call == Call::kSetRenderTarget ||\\n      tracked.call == Call::kSetDepthStencilSurface) {\\n    for (uint32_t i = 0; i < 5; ++i)\\n      HulkRememberSurface(ReadBoundSurface(base, tracked.device, i), i);\\n  }\\n  if (tracked.call != g_call.call) return;\"},{\"path\":\"src/renderer.cpp\",\"old\":\"  synthetic.device = device;\\n  CaptureDraw(synthetic, tracker, base);\",\"new\":\"  synthetic.device = device;\\n  std::array<GuestSurface, 5> packet_surfaces{};\\n  if (!HulkPacketSurfaces(tracker, base, device, packet_surfaces)) return;\\n  CaptureDraw(synthetic, tracker, base, &packet_surfaces);\"}]")
def patch_text(source, rules):
    done=[e["new"] in source for e in rules]
    if all(done): return source,False
    if any(done): raise ValueError("Partial PM4 surface patch")
    for e in rules:
        if source.count(e["old"])!=1: raise ValueError("Pinned NativeX/earlier-patch anchor mismatch: "+e["old"][:65])
    for e in rules: source=source.replace(e["old"],e["new"],1)
    return source,True
def main():
    if len(sys.argv)!=2: raise SystemExit("Usage: patch_native_x_hulk_packet_surfaces.py <NativeX source>")
    root=Path(sys.argv[1]).resolve()
    sha=subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD"],text=True).strip()
    if sha!=PIN: raise ValueError("Unexpected NativeX SHA "+sha)
    modified=[]
    for rel in ("src/state.h","src/state.cpp","src/renderer.cpp"):
        p=root/rel
        new,changed=patch_text(p.read_text(encoding="utf8"),[e for e in EDITS if e["path"]==rel])
        modified.append((p,new,changed))
    if len({v[2] for v in modified})!=1: raise ValueError("Partial NativeX patch state; no writes")
    for p,new,changed in modified:
        if changed: p.write_text(new,encoding="utf8",newline="\n")
    print("Hulk per-PM4 draw surface snapshot:", "installed" if modified[0][2] else "already installed")
if __name__=="__main__": main()
